<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {scheduleApi} from '../schedules'
const props=defineProps<{assignments:any[]}>()
const students=ref<any[]>([]),search=ref(''),error=ref(''),loading=ref(false),opened=ref('')
const dates=computed(()=>[...new Set(props.assignments.map(h=>h.assigned_on))].sort())
const onDate=(date:string)=>props.assignments.filter(h=>h.assigned_on===date).sort((a,b)=>a.id-b.id)
const visible=computed(()=>students.value.filter(s=>(s.full_name+' '+s.login_id).toLowerCase().includes(search.value.trim().toLowerCase())))
const symbol=(status:string)=>status==='submitted'||status==='reviewed'?'O':status==='missing'?'X':status==='late'?'–':'·'
const description=(status:string)=>status==='submitted'?'Done':status==='reviewed'?'Reviewed':status==='missing'?'Not done':status==='late'?'Late submission':'Unmarked'
async function load(){loading.value=true;error.value='';students.value=[];try{const results=await Promise.all(props.assignments.map(h=>scheduleApi(`teacher/homework/${h.id}/progress`)));const roster=new Map<number,any>();results.forEach((r,i)=>r.students.forEach((s:any)=>{if(!roster.has(s.id))roster.set(s.id,{...s,marks:{}});roster.get(s.id).marks[props.assignments[i]!.id]=s.status}));students.value=[...roster.values()]}catch(e){error.value=e instanceof Error?e.message:'Unable to load homework register.'}finally{loading.value=false}}
onMounted(load)
</script>
<template><div class="register"><p class="help">O Done · X Not done · – Late submission · · Unmarked. Mark each assignment using Track homework. Hover, focus or tap a date to see homework names.</p><div class="controls"><label>Find a student<input v-model="search" type="search" placeholder="Name or student ID"></label><button type="button" class="secondary" :disabled="loading" @click="load">Refresh register</button></div><p v-if="loading" role="status">Loading register…</p><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="!assignments.length">No homework created for this class yet.</p><div v-else class="scroll"><table><thead><tr><th scope="col">Student</th><th v-for="date in dates" :key="date" scope="col"><div class="date-heading"><button type="button" :aria-expanded="opened===date" :aria-label="date+': '+onDate(date).map(h=>h.title).join(', ')" @click="opened=opened===date?'':date">{{date}}</button><div class="date-tip" :class="{shown:opened===date}" role="tooltip"><span v-for="(h,i) in onDate(date)" :key="h.id">{{onDate(date).length>1?(i+1)+'. ':''}}{{h.title}}</span></div></div></th></tr></thead><tbody><tr v-for="s in visible" :key="s.id"><th scope="row">{{s.full_name}}<small>{{s.login_id}}</small></th><td v-for="date in dates" :key="date"><span class="marks"><span v-for="(h,i) in onDate(date)" :key="h.id" class="mark" :class="s.marks[h.id]" :title="h.title+': '+description(s.marks[h.id])" :aria-label="h.title+': '+description(s.marks[h.id])"><small v-if="onDate(date).length>1">{{i+1}}</small>{{symbol(s.marks[h.id])}}</span></span></td></tr></tbody></table></div><p v-if="!loading&&assignments.length&&!visible.length&&!error">No students match.</p><p v-if="dates.some(d=>onDate(d).length>1)" class="help">Numbered marks follow the homework order shown when you open the date. Each assignment keeps its own result.</p></div></template>
<style scoped>
.register{min-width:0}.help{font-size:13px;color:#60736e;line-height:1.6}.controls{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin:16px 0}.controls label{flex:1;min-width:160px;margin:0}.controls input{width:100%;min-height:44px;font:inherit;padding:10px;border:1px solid #bccfc5;border-radius:8px}.controls button{width:auto;min-height:44px;margin:0;padding:10px 14px}.scroll{overflow:auto;max-height:570px;border:1px solid #dce5df;border-radius:10px}table{width:100%;border-collapse:separate;border-spacing:0;font-size:14px}th,td{padding:12px;border-bottom:1px solid #dce5df;border-right:1px solid #dce5df;text-align:center;min-width:124px}thead th{position:sticky;top:0;background:#edf4ef;z-index:2}tbody th{position:sticky;left:0;background:white;text-align:left;min-width:180px;z-index:1}thead th:first-child{left:0;z-index:3;text-align:left}small{display:block;font-size:11px;color:#60736e;margin-top:4px}.date-heading{position:relative}.date-heading button{background:transparent;color:#243e33;width:auto;margin:0;padding:6px;font:inherit;font-weight:600;border:0;min-height:44px}.date-tip{display:none;position:absolute;top:100%;left:0;width:220px;max-width:60vw;padding:12px;background:#243e33;color:white;border-radius:8px;text-align:left;box-shadow:0 4px 14px #0003;font-weight:400;line-height:1.6;z-index:5}thead th:last-child .date-tip{left:auto;right:0}.date-tip span{display:block}.date-heading:hover .date-tip,.date-heading:focus-within .date-tip,.date-tip.shown{display:block}.marks{display:flex;justify-content:center;gap:12px}.mark{font-size:18px;font-weight:700}.mark.submitted,.mark.reviewed{color:#185b38}.mark.missing{color:#a22f24}.mark.late{color:#805c12}.mark small{margin:0;font-weight:400}
</style>
